const fs=require('node:fs'),crypto=require('node:crypto'),assert=require('node:assert/strict'),{chromium,webkit}=require('playwright');const engine=process.env.NATIVE_BROWSER||'chromium',out='qa-output/native-'+engine;fs.mkdirSync(out,{recursive:true});const specs=JSON.parse(fs.readFileSync('research/common-cases/manifest.json')),sha=a=>crypto.createHash('sha256').update(a).digest('hex');(async()=>{const b=await({chromium,webkit}[engine]).launch(engine==='chromium'?{headless:true,args:['--no-sandbox','--use-angle=swiftshader','--enable-unsafe-swiftshader']}:{headless:true}),p=await b.newPage({viewport:{width:1440,height:1000}}),errors=[],rows=[];p.on('pageerror',e=>errors.push(e.message));await p.goto('http://127.0.0.1:8765/qa/common-native.html');await p.waitForFunction(()=>window.commonNativeQA?.ready,null,{timeout:180000});for(const row of specs.cases){await p.evaluate(s=>window.commonNativeQA.apply(s),row.state);const actual=Float32Array.from(await p.evaluate(()=>Array.from(window.commonNativeQA.positions()))),raw=fs.readFileSync('research/common-cases/'+row.name+'.f32'),expected=new Float32Array(raw.buffer,raw.byteOffset,raw.byteLength/4);let max=0;for(let i=0;i<actual.length;i++)max=Math.max(max,Math.abs(actual[i]-expected[i]));assert(max<=1e-6,row.name+' cross-engine metre residual '+max);await p.evaluate(s=>window.commonNativeQA.apply(s),row.state);const repeated=Float32Array.from(await p.evaluate(()=>Array.from(window.commonNativeQA.positions())));assert.equal(sha(repeated),sha(actual));const a=await p.evaluate(()=>window.commonNativeQA.archive());await p.evaluate(s=>window.commonNativeQA.apply(s),specs.cases[0].state);await p.evaluate(a=>window.commonNativeQA.restore(a),a);const restored=Float32Array.from(await p.evaluate(()=>Array.from(window.commonNativeQA.positions())));assert.equal(sha(restored),sha(actual));assert.equal((await p.evaluate(()=>window.commonNativeQA.pixel())).error,0);for(const view of['front','rear','side']){await p.evaluate(v=>window.commonNativeQA.view(v),view);await p.screenshot({path:out+'/'+row.name+'-'+view+'.png'});}rows.push({name:row.name,maxCrossEngineMetres:max,sameEngineRepeatAndArchiveByteExact:true});}assert.deepEqual(errors,[]);fs.writeFileSync(out+'/report.json',JSON.stringify({passed:true,engine,version:b.version(),actualBrowserForward:true,fingerprint:specs.fingerprint,rows,errors,notFullMergedModel:true,visualReviewStillRequired:true},null,2));await b.close();})().catch(e=>{console.error(e);fs.writeFileSync(out+'/failure.txt',String(e.stack));process.exit(1)});
